<?php require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';require __DIR__.'/../includes/customer-auth.php';if(current_customer()){header('Location: ../account.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$ip=$_SERVER['REMOTE_ADDR']??'';$q=$pdo->prepare('SELECT COUNT(*) FROM customer_login_attempts WHERE ip_address=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE) AND succeeded=0');$q->execute([$ip]);if((int)$q->fetchColumn()>=10){http_response_code(429);$error='Terlalu banyak percobaan. Coba lagi 15 menit.';}else{$q=$pdo->prepare('SELECT id,name,email,phone,password_hash,active FROM customers WHERE email=? LIMIT 1');$q->execute([$email]);$c=$q->fetch();$ok=$c&&$c['active']&&password_verify($_POST['password']??'',$c['password_hash']);$pdo->prepare('INSERT INTO customer_login_attempts(ip_address,email,succeeded) VALUES(?,?,?)')->execute([$ip,mb_substr($email,0,190),$ok?1:0]);if($ok){session_regenerate_id(true);unset($_SESSION['customer_login_csrf']);$_SESSION['customer']=['id'=>(int)$c['id'],'name'=>$c['name'],'email'=>$c['email'],'phone'=>$c['phone']];$pdo->prepare('UPDATE customers SET last_login=NOW() WHERE id=?')->execute([$c['id']]);header('Location: ../checkout.php');exit;}$error='Email atau kata sandi tidak valid.';}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masuk — TokoKita</title><link rel="stylesheet" href="../assets/style.css"><style>.auth{max-width:480px;margin:45px auto;padding:26px}.auth .field{margin:14px 0}</style></head><body><?php include __DIR__.'/../includes/header.php'?><?php customer_nav()?><main class="wrap"><form class="panel auth" method="post"><span class="eyebrow">TOKOKITA</span><h1 class="page-title">Masuk ke akun</h1><p class="muted">Pilih alamat tersimpan saat checkout agar lebih cepat.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Email</label><input type="email" name="email" maxlength="190" autocomplete="username" required></div><div class="field"><label>Kata sandi</label><input type="password" name="password" maxlength="200" autocomplete="current-password" required></div><button class="btn full">Masuk</button><p>Belum punya akun? <a href="register.php">Daftar sekarang</a></p></form></main><?php include __DIR__.'/../includes/footer.php'?></body></html>